import math

def tau(n):
    if n == 1:
        return 1
    count = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            count[d] = count.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        count[temp] = count.get(temp, 0) + 1

    result = 1
    for exponent in count.values():
        result *= (exponent + 1)
    return result

solutions = []
for k in range(1, 10):
    LHS = tau(2 * (k**3))
    RHS = 2 * k
    print(f"k={k}: tau(2k^3) = {LHS}, 2k = {RHS}. {'LHS > RHS' if LHS > RHS else ('LHS < RHS' if LHS < RHS else 'LHS = RHS')}")
    if LHS == RHS:
        solutions.append(k)

print(f"Solutions found for k in [1, 9]: {solutions}")

